rule.example:
fun collectBad(completionService: CompletionService<List<Any>>): Future<List<Any>> {
    return completionService.take() // bad
}

fun collectGood(completionService: CompletionService<List<Any>>): Future<List<Any>>? {
    return completionService.poll(3L, TimeUnit.SECONDS) // good
}

fun bad(complFuture: CompletableFuture<String>): String {
    return complFuture.get() // bad
}

fun good(complFuture: CompletableFuture<String>): String {
    return complFuture.get(10, TimeUnit.SECONDS) // good
}

property.value:
(: future.join() without any timeout method anywhere in the same function body :)
//PostfixUnaryExpression[
    pmd-kotlin:matchesSig('java.util.concurrent.Future#join()')
    and ./PostfixUnarySuffix/NavigationSuffix[@Identifier='join']
    and not(
        ancestor::FunctionBody//PostfixUnaryExpression[
            pmd-kotlin:matchesSig('java.util.concurrent.Future#get(_,java.util.concurrent.TimeUnit)')
            or pmd-kotlin:matchesSig('java.util.concurrent.CompletableFuture#orTimeout(_,java.util.concurrent.TimeUnit)')
            or pmd-kotlin:matchesSig('java.util.concurrent.CompletableFuture#completeOnTimeout(_,_,java.util.concurrent.TimeUnit)')
        ]
    )
]

rule.example:
fun getOrdersBad(futures: List<CompletableFuture<Order>>): List<Order> {
    return futures
        .filter { it.isDone && !it.isCompletedExceptionally }
        .map { it.join() } // bad, no timeout provided
}

fun getOrdersGood(futures: List<CompletableFuture<Order>>): List<Order> {
    val allResult = CompletableFuture.allOf(*futures.toTypedArray())
    try {
        allResult.get(5L, TimeUnit.SECONDS) // good - timeout
    } catch (e: Exception) { }
    return futures
        .filter { it.isDone && !it.isCompletedExceptionally }
        .map { it.join() } // good - timeout provided above
}

class Foo {
    private val asyncPool = Executors.newFixedThreadPool(8)

    fun bad(accounts: List<Any>) {
        val futures = accounts.map {
            CompletableFuture.supplyAsync { isAccountBlocked(it) } // bad, uses common pool
        }
    }

    fun good(accounts: List<Any>) {
        val futures = accounts.map {
            CompletableFuture.supplyAsync({ isAccountBlocked(it) }, asyncPool) // good
        }
    }
}
